"""Retention expiry date helpers."""
import calendar
from datetime import date


def _shift_month(year: int, month: int, months: int) -> tuple[int, int]:
    idx = year * 12 + (month - 1) + months
    return idx // 12, idx % 12 + 1


def _days_in_month(year: int, month: int) -> int:
    return calendar.monthrange(year, month)[1]


def retention_end(created: date, months: int, policy: str) -> date:
    """Compute the retention end date for a record created on ``created``.

    policy: 'anniversary' keeps the day-of-month (clamped to month end);
            'month_end' lands on the last day of the reached month.
    """
    if months < 0:
        raise ValueError("months must be non-negative")
    y, m = _shift_month(created.year, created.month, months)
    if policy == "anniversary":
        d = min(created.day, _days_in_month(y, m))
    elif policy == "month_end":
        d = _days_in_month(y, m)
    else:
        raise ValueError(f"unknown policy: {policy!r}")
    return date(y, m, d)


def is_expired(created: date, months: int, policy: str, today: date) -> bool:
    """Expired iff today falls AFTER retention_end (the day after counts)."""
    return today > retention_end(created, months, policy)

